import Citadel
import CryptoKit
import Foundation
import NIOCore
import NIOSSH
import Synchronization

// MARK: - 1. Fingerprint from the OpenSSH text form, Foundation + CryptoKit only.

struct HostKeyFingerprint: Hashable, Sendable {
    let openSSHPublicKey: String
    let sha256: String

    init?(openSSHPublicKey: String) {
        let fields = openSSHPublicKey.split(separator: " ", maxSplits: 2, omittingEmptySubsequences: true)
        guard fields.count >= 2, let wire = Data(base64Encoded: String(fields[1])) else { return nil }
        self.openSSHPublicKey = openSSHPublicKey
        let digest = SHA256.hash(data: wire)
        let base64 = Data(digest).base64EncodedString()
        sha256 = "SHA256:" + base64.replacingOccurrences(of: "=", with: "")
    }
}

// MARK: - 2. TOFU: records the offered key and refuses, so the UI can ask.

struct UnknownHostKey: Error {
    let fingerprint: HostKeyFingerprint
}

final class RecordingHostKeyValidator: NIOSSHClientServerAuthenticationDelegate, Sendable {
    private let offered = Mutex<String?>(nil)

    var offeredKey: String? { offered.withLock { $0 } }

    func validateHostKey(hostKey: NIOSSHPublicKey, validationCompletePromise: EventLoopPromise<Void>) {
        let text = String(openSSHPublicKey: hostKey)
        offered.withLock { $0 = text }
        validationCompletePromise.fail(UnknownHostKey(fingerprint: HostKeyFingerprint(openSSHPublicKey: text)!))
    }
}

// MARK: - 3. The value type the UI sees. No Citadel types in it.

struct RemoteFile: Hashable, Sendable, Identifiable {
    enum Kind: Sendable { case file, directory, symlink, other }

    var id: String { path }
    let name: String
    let path: String
    let kind: Kind
    let size: UInt64?
    let modified: Date?
    let mode: UInt32?

    /// The file type lives in the high bits of the POSIX mode; SFTP carries no
    /// separate field for it. `longname` is the only fallback when a server omits
    /// permissions altogether.
    static func kind(mode: UInt32?, longname: String) -> Kind {
        guard let mode else {
            return longname.first == "d" ? .directory : (longname.first == "l" ? .symlink : .file)
        }
        switch mode & 0o170000 {
        case 0o040000: return .directory
        case 0o120000: return .symlink
        case 0o100000: return .file
        default: return .other
        }
    }
}

// MARK: - 4. The actor. SSHClient is a non-Sendable final class and must not escape.

actor SSHFileSystem {
    private var client: SSHClient?

    func connect(host: String, port: Int, username: String, password: String, pinned: String?) async throws {
        let validator: SSHHostKeyValidator
        if let pinned {
            validator = .trustedKeys([try NIOSSHPublicKey(openSSHPublicKey: pinned)])
        } else {
            validator = .custom(RecordingHostKeyValidator())
        }
        client = try await SSHClient.connect(
            host: host,
            port: port,
            authenticationMethod: .passwordBased(username: username, password: password),
            hostKeyValidator: validator,
            reconnect: .never
        )
    }

    func list(_ path: String) async throws -> [RemoteFile] {
        guard let client else { throw UnknownHostKey(fingerprint: HostKeyFingerprint(openSSHPublicKey: "x y")!) }
        let sftp = try await client.openSFTP()
        let listings = try await sftp.listDirectory(atPath: path)
        return listings.flatMap(\.components).map { component in
            let mode = component.attributes.permissions
            return RemoteFile(
                name: component.filename,
                path: path.hasSuffix("/") ? path + component.filename : path + "/" + component.filename,
                kind: RemoteFile.kind(mode: mode, longname: component.longname),
                size: component.attributes.size,
                modified: component.attributes.accessModificationTime
                    .map { Date(timeIntervalSince1970: TimeInterval($0.modificationTime)) },
                mode: mode
            )
        }
    }

    func read(_ path: String) async throws -> Data {
        guard let client else { return Data() }
        let sftp = try await client.openSFTP()
        return try await sftp.withFile(filePath: path, flags: .read) { file in
            let buffer = try await file.readAll()
            return Data(buffer.readableBytesView)
        }
    }

    func write(_ data: Data, to path: String) async throws {
        guard let client else { return }
        let sftp = try await client.openSFTP()
        try await sftp.withFile(filePath: path, flags: [.write, .create, .truncate]) { file in
            try await file.write(ByteBuffer(bytes: data), at: 0)
        }
    }

    func makeDirectory(at path: String) async throws {
        guard let client else { return }
        try await client.openSFTP().createDirectory(atPath: path)
    }

    func removeFile(_ path: String) async throws {
        guard let client else { return }
        try await client.openSFTP().remove(at: path)
    }

    func removeDirectory(_ path: String) async throws {
        guard let client else { return }
        try await client.openSFTP().rmdir(at: path)
    }

    func rename(_ path: String, to newPath: String) async throws {
        guard let client else { return }
        try await client.openSFTP().rename(at: path, to: newPath)
    }

    func close() async throws {
        try await client?.close()
        client = nil
    }
}

