import NIOSSH
import Synchronization

// Variant B: actor, SSHClient held as nonisolated(unsafe).
actor VariantB {
    private let group: MultiThreadedEventLoopGroup
    nonisolated(unsafe) private var client: SSHClient?
    private var sftp: SFTPClient?

    init(group: MultiThreadedEventLoopGroup) { self.group = group }

    func connect(host: String, username: String, password: String) async throws {
        let client = try await SSHClient.connect(
            host: host,
            authenticationMethod: .passwordBased(username: username, password: password),
            hostKeyValidator: .acceptAnything(),
            reconnect: .never,
            group: group
        )
        self.client = client
        sftp = try await client.openSFTP()
    }

    func list(_ path: String) async throws -> [String] {
        guard let sftp else { return [] }
        return try await sftp.listDirectory(atPath: path).flatMap(\.components).map(\.filename)
    }

    func close() async throws {
        try await sftp?.close()
        try await client?.close()
        sftp = nil
        client = nil
    }
}

// Variant C: Sendable final class, SSHClient behind a Mutex, SFTPClient reused.
final class VariantC: Sendable {
    private let group: MultiThreadedEventLoopGroup
    private let held = Mutex<(ssh: SSHClient, sftp: SFTPClient)?>(nil)

    init(group: MultiThreadedEventLoopGroup) { self.group = group }

    func connect(host: String, username: String, password: String) async throws {
        let client = try await SSHClient.connect(
            host: host,
            authenticationMethod: .passwordBased(username: username, password: password),
            hostKeyValidator: .acceptAnything(),
            reconnect: .never,
            group: group
        )
        let sftp = try await client.openSFTP()
        held.withLock { $0 = (client, sftp) }
    }

    func list(_ path: String) async throws -> [String] {
        guard let sftp = held.withLock({ $0?.sftp }) else { return [] }
        return try await sftp.listDirectory(atPath: path).flatMap(\.components).map(\.filename)
    }

    func close() async throws {
        guard let pair = held.withLock({ let p = $0; $0 = nil; return p }) else { return }
        try await pair.sftp.close()
        try await pair.ssh.close()
    }
}

