import Foundation

/// One entry in a directory on the robot.
///
/// Deliberately free of every Citadel type, so a screen, a preview and a test all
/// speak the same values and only ``SSHFileSystem`` ever sees an SFTP message.
public struct RemoteFile: Hashable, Sendable, Identifiable {
    public enum Kind: Hashable, Sendable {
        case file
        case directory
        case symlink
        /// A socket, a device node, a FIFO. Listed, never opened.
        case other
    }

    public var id: String { path }

    public let name: String
    public let path: String
    public let kind: Kind
    public let size: UInt64?
    public let modified: Date?
    /// The POSIX mode as the server sent it, for the permissions column.
    public let mode: UInt32?

    public init(
        name: String,
        path: String,
        kind: Kind,
        size: UInt64? = nil,
        modified: Date? = nil,
        mode: UInt32? = nil
    ) {
        self.name = name
        self.path = path
        self.kind = kind
        self.size = size
        self.modified = modified
        self.mode = mode
    }

    public var isDirectory: Bool { kind == .directory }

    /// SFTP carries no field for the kind of thing an entry is: it lives in the
    /// high bits of the mode, the same `S_IFMT` bits `stat(2)` reports. A server
    /// that sends no permissions at all leaves only `longname`, whose first
    /// character is the one from `ls -l`.
    public static func kind(mode: UInt32?, longname: String) -> Kind {
        guard let mode else {
            switch longname.first {
            case "d": return .directory
            case "l": return .symlink
            case "-": return .file
            default: return .other
            }
        }
        switch mode & 0o170000 {
        case 0o040000: return .directory
        case 0o120000: return .symlink
        case 0o100000: return .file
        default: return .other
        }
    }

    /// `drwxr-xr-x`, built from the mode rather than taken from `longname` — the
    /// latter is the server's own rendering and varies between implementations.
    public static func permissionsText(mode: UInt32?, kind: Kind) -> String? {
        guard let mode else { return nil }
        let prefix: Character = switch kind {
        case .directory: "d"
        case .symlink: "l"
        case .file: "-"
        case .other: "?"
        }
        let bits = ["r", "w", "x"]
        var text = String(prefix)
        for shift in [6, 3, 0] {
            let triad = (mode >> UInt32(shift)) & 0o7
            for (index, bit) in bits.enumerated() {
                text += triad & UInt32(0o4 >> index) != 0 ? bit : "-"
            }
        }
        return text
    }
}

public extension RemoteFile {
    /// Joins a directory to a child name without doubling the separator, which
    /// `"/"` — the one path where the parent already ends in one — otherwise does.
    static func joining(_ directory: String, _ name: String) -> String {
        directory.hasSuffix("/") ? directory + name : directory + "/" + name
    }

    /// The parent of a path, or nil at the root. Trailing slashes are ignored so
    /// that `/a/b/` and `/a/b` answer the same thing.
    static func parent(of path: String) -> String? {
        var trimmed = path
        while trimmed.count > 1, trimmed.hasSuffix("/") { trimmed.removeLast() }
        guard trimmed != "/", let slash = trimmed.lastIndex(of: "/") else { return nil }
        return slash == trimmed.startIndex ? "/" : String(trimmed[trimmed.startIndex ..< slash])
    }
}

import CryptoKit
import Foundation

/// An SSH host key, in the form a user can compare against `ssh-keygen -lf`.
///
/// Built from the OpenSSH text form rather than from a `NIOSSHPublicKey`, and that
/// is what keeps this type — and its tests — free of SwiftNIO. The base64 field of
/// `"ssh-ed25519 AAAAC3Nza…"` *is* the SSH wire encoding of the key, which is
/// exactly what OpenSSH hashes to print a fingerprint. So the whole computation is
/// Foundation plus one SHA-256.
public struct HostKeyFingerprint: Hashable, Sendable {
    /// The full `"<algorithm> <base64>"` line, which is what gets pinned: a text
    /// round-trip through `NIOSSHPublicKey(openSSHPublicKey:)` beats storing an
    /// opaque blob whose layout belongs to a dependency.
    public let openSSHPublicKey: String
    /// `ssh-ed25519`, `ecdsa-sha2-nistp256`, and so on.
    public let algorithm: String
    /// `SHA256:` followed by unpadded base64, the way OpenSSH 6.8+ prints it.
    public let sha256: String

    public init?(openSSHPublicKey: String) {
        let line = openSSHPublicKey.trimmingCharacters(in: .whitespacesAndNewlines)
        let fields = line.split(separator: " ", maxSplits: 2, omittingEmptySubsequences: true)
        guard fields.count >= 2, let wire = Data(base64Encoded: String(fields[1])) else { return nil }
        // Keep only algorithm and key: an `authorized_keys`-style comment is not
        // part of the identity and would make two pins of one key.
        self.openSSHPublicKey = "\(fields[0]) \(fields[1])"
        algorithm = String(fields[0])
        let digest = Data(SHA256.hash(data: wire)).base64EncodedString()
        sha256 = "SHA256:" + digest.replacingOccurrences(of: "=", with: "")
    }

    /// Grouped for reading aloud over a desk, which is the whole point of showing
    /// it. The `SHA256:` prefix stays attached to the first group.
    public var groupedForDisplay: String {
        let body = sha256.dropFirst("SHA256:".count)
        let groups = stride(from: 0, to: body.count, by: 11).map { offset -> String in
            let start = body.index(body.startIndex, offsetBy: offset)
            let end = body.index(start, offsetBy: min(11, body.count - offset))
            return String(body[start ..< end])
        }
        return "SHA256:" + groups.joined(separator: " ")
    }
}

import Foundation

/// Everything this module can fail with.
///
/// No `LocalizedError`: the sentence a user reads is chosen by the screen that
/// asked, in its own language catalogue, the way `RunningAppCaption` maps a daemon
/// process state rather than letting the domain carry words.
public enum ReachySSHError: Error, Equatable, Sendable {
    case notConnected
    /// First contact with this robot. Carries the key to show and then pin.
    case hostKeyUnknown(HostKeyFingerprint)
    /// A pinned robot answered with a different key. Either the robot was
    /// reflashed, or something is sitting in the middle.
    case hostKeyChanged(pinned: HostKeyFingerprint, offered: HostKeyFingerprint)
    case authenticationFailed
    case pathNotFound(String)
    case notPermitted(String)
    /// `rmdir` on a directory with contents. The server refuses; we do not recurse.
    case directoryNotEmpty(String)
    /// A phone must not pull a multi-gigabyte model file into memory to show it.
    case fileTooLarge(bytes: UInt64, limit: Int)
    /// Anything the SSH or SFTP layer reported that has no case of its own. The
    /// string is the server's or the library's, so it stays a `String`.
    case transport(String)
    case keychain(OSStatus)

    /// Whether retrying with the same inputs could plausibly succeed. A wrong
    /// password or a missing path will not fix itself; a dropped channel might.
    public var isRetryable: Bool {
        switch self {
        case .notConnected, .transport: true
        case .hostKeyUnknown, .hostKeyChanged, .authenticationFailed, .pathNotFound,
             .notPermitted, .directoryNotEmpty, .fileTooLarge, .keychain: false
        }
    }
}

import Foundation

/// Where a robot's files are reached, and the seam a screen is written against.
///
/// A protocol rather than the concrete actor so that a preview and a test can hand
/// a screen a settled directory without a robot, an SSH server or a network — the
/// same reason `RobotAPIClient` exists one package over.
public protocol RobotFileSystem: Sendable {
    /// Opens a session, or throws ``ReachySSHError/hostKeyUnknown(_:)`` when this
    /// robot's key has never been confirmed. Idempotent: calling it on a live
    /// session is a no-op rather than a second connection.
    func connect(_ credentials: SSHCredentials) async throws
    func disconnect() async

    func list(_ path: String) async throws -> [RemoteFile]
    /// Reads a whole file, refusing anything over `limit` rather than growing to
    /// fit it.
    func read(_ path: String, limit: Int) async throws -> Data
    /// Creates or truncates. This is also how an edit lands: the file goes to the
    /// device, an editor there changes it, and it comes back over the same path.
    func write(_ data: Data, to path: String) async throws
    func makeDirectory(at path: String) async throws
    /// Picks `remove` or `rmdir` from the entry's kind, which is why this takes a
    /// ``RemoteFile`` and not a path.
    func remove(_ file: RemoteFile) async throws
    func rename(_ path: String, to newPath: String) async throws
}

/// The robot's SSH login. Not `Codable` on purpose — the REDACTED belongs in the
/// Keychain as a value, never in anything with a `write(to:)`.
public struct SSHCredentials: Hashable, Sendable {
    public var host: String
    public var port: Int
    public var username: String
    public var REDACTED: String

    /// Reachy Mini Wireless ships with OpenSSH enabled and this account. Offered
    /// as a prefill and never assumed: a robot whose REDACTED has been changed —
    /// which the UI should encourage — must still be reachable.
    public static let defaultUsername = "pollen"
    public static let defaultPort = 22

    public init(host: String, port: Int = SSHCredentials.defaultPort, username: String, REDACTED: String) {
        self.host = host
        self.port = port
        self.username = username
        self.REDACTED = REDACTED
    }
}

/// Pinned host keys, one per robot.
///
/// Keyed by the robot's hardware id rather than by its address (project rule 4): a
/// robot moves between networks and addresses, and its host key does not.
public protocol HostKeyStore: Sendable {
    func pinnedKey(forRobot robot: String) throws -> String?
    func pin(_ openSSHPublicKey: String, forRobot robot: String) throws
    func forget(robot: String) throws
}

/// Saved REDACTEDs, one per robot, under the same key as the pinned host key.
public protocol SSHCredentialStore: Sendable {
    func credentials(forRobot robot: String) throws -> SSHCredentials?
    func save(_ credentials: SSHCredentials, forRobot robot: String) throws
    func clear(robot: String) throws
}

import Foundation
import Security

/// The Keychain shape both stores share.
///
/// Written against `Security` directly, like `KeychainHFTokenStore`: the surface is
/// three calls, and a dependency that holds a credential is one more thing to
/// audit. Items are `ThisDeviceOnly` for the same reason a Hugging Face token is —
/// a robot password restored onto another device is one the user never knowingly
/// put there.
private enum KeychainItem {
    static func load(service: String, account: String) throws -> Data? {
        var query = base(service: service, account: account)
        query[kSecReturnData as String] = true
        query[kSecMatchLimit as String] = kSecMatchLimitOne

        var result: CFTypeRef?
        let status = SecItemCopyMatching(query as CFDictionary, &result)
        switch status {
        case errSecSuccess: return result as? Data
        case errSecItemNotFound: return nil
        default: throw ReachySSHError.keychain(status)
        }
    }

    static func save(_ data: Data, service: String, account: String) throws {
        let query = base(service: service, account: account)
        let update = SecItemUpdate(query as CFDictionary, [kSecValueData as String: data] as CFDictionary)
        if update == errSecSuccess { return }
        guard update == errSecItemNotFound else { throw ReachySSHError.keychain(update) }

        var item = query
        item[kSecValueData as String] = data
        item[kSecAttrAccessible as String] = kSecAttrAccessibleAfterFirstUnlockThisDeviceOnly
        let status = SecItemAdd(item as CFDictionary, nil)
        guard status == errSecSuccess else { throw ReachySSHError.keychain(status) }
    }

    static func delete(service: String, account: String) throws {
        let status = SecItemDelete(base(service: service, account: account) as CFDictionary)
        guard status == errSecSuccess || status == errSecItemNotFound else {
            throw ReachySSHError.keychain(status)
        }
    }

    private static func base(service: String, account: String) -> [String: Any] {
        [
            kSecClass as String: kSecClassGenericPassword,
            kSecAttrService as String: service,
            kSecAttrAccount as String: account,
        ]
    }
}

/// Pinned host keys in the Keychain, one item per robot.
public struct KeychainHostKeyStore: HostKeyStore {
    private let service: String

    public init(service: String = "com.alexey1312.ReachyMini.ssh.hostkey") {
        self.service = service
    }

    public func pinnedKey(forRobot robot: String) throws -> String? {
        guard let data = try KeychainItem.load(service: service, account: robot) else { return nil }
        return String(data: data, encoding: .utf8)
    }

    public func pin(_ openSSHPublicKey: String, forRobot robot: String) throws {
        try KeychainItem.save(Data(openSSHPublicKey.utf8), service: service, account: robot)
    }

    public func forget(robot: String) throws {
        try KeychainItem.delete(service: service, account: robot)
    }
}

/// Saved SSH passwords in the Keychain, one item per robot.
///
/// Host and port are *not* stored: the session already knows where the robot is,
/// and a remembered address is exactly the mistake project rule 4 warns about.
/// Only the username and the password are kept.
public struct KeychainSSHCredentialStore: SSHCredentialStore {
    private struct Stored: Codable {
        var username: String
        var password: String
    }

    private let service: String

    public init(service: String = "com.alexey1312.ReachyMini.ssh.login") {
        self.service = service
    }

    public func credentials(forRobot robot: String) throws -> SSHCredentials? {
        guard let data = try KeychainItem.load(service: service, account: robot),
              let stored = try? JSONDecoder().decode(Stored.self, from: data)
        else { return nil }
        // Host and port are filled in by the caller, which is the only thing that
        // knows where this robot is right now.
        return SSHCredentials(host: "", username: stored.username, password: stored.password)
    }

    public func save(_ credentials: SSHCredentials, forRobot robot: String) throws {
        let stored = Stored(username: credentials.username, password: credentials.password)
        try KeychainItem.save(try JSONEncoder().encode(stored), service: service, account: robot)
    }

    public func clear(robot: String) throws {
        try KeychainItem.delete(service: service, account: robot)
    }
}

import Citadel
import Foundation
import NIOCore
import NIOPosix
import NIOSSH
import Synchronization

// Citadel marks the `SFTPClient` it hands out `Sendable` but not the `SSHClient`
// that opened it, though both are driven through the same NIO `Channel`. Without
// this, an `SSHClient` built inside an `async` function is task-isolated and cannot
// be stored *at all*: an actor property fails with "sending 'client' risks causing
