import ReachyDesign
import ReachySSH
import SwiftUI

/// One entry in the robot's file listing.
struct RemoteFileRow: View {
    let file: RemoteFile

    var body: some View {
        HStack(spacing: Space.md) {
            Image(systemName: symbol)
                .foregroundStyle(file.isDirectory ? AnyShapeStyle(.tint) : Tone.quiet.style)
                .frame(width: Space.xl)
            VStack(alignment: .leading, spacing: Space.xxs) {
                Text(file.name)
                    .font(Typography.rowTitleCompact)
                    .lineLimit(1)
                    .truncationMode(.middle)
                if let detail {
                    Text(detail)
                        .font(Typography.status)
                        .foregroundStyle(.secondary)
                }
            }
            Spacer(minLength: 0)
            if file.isDirectory {
                // The mirroring glyph, not `chevron.right`: a right-to-left
                // language needs no second pass.
                Image(systemName: "chevron.forward")
                    .font(Typography.status)
                    .foregroundStyle(.tertiary)
            }
        }
    }

    private var symbol: String {
        switch file.kind {
        case .directory: "folder"
        case .symlink: "arrow.turn.down.right"
        case .other: "questionmark.square.dashed"
        case .file: "doc"
        }
    }

    /// Size, permissions and date on one line, in that order, and each of them
    /// optional: SFTP is free to omit every one.
    private var detail: String? {
        var parts: [String] = []
        if !file.isDirectory, let size = file.size {
            parts.append(ByteCountFormatter.string(fromByteCount: Int64(size), countStyle: .file))
        }
        if let permissions = RemoteFile.permissionsText(mode: file.mode, kind: file.kind) {
            parts.append(permissions)
        }
        if let modified = file.modified {
            parts.append(modified.formatted(date: .abbreviated, time: .shortened))
        }
        return parts.isEmpty ? nil : parts.joined(separator: "  ·  ")
    }
}

import ReachyDesign
import ReachySSH
import SwiftUI

/// Asks for the robot's SSH password.
///
/// Inline rather than a sheet: the screen has nothing to show behind it, and a
/// model built inside a `.sheet` content closure is silently replaced every time
/// the parent updates — the trap `RootSheets` documents.
struct SSHPasswordForm: View {
    @Bindable var model: RobotFilesModel
    let onConnect: () -> Void

    var body: some View {
        Form {
            Section {
                TextField(.reachy("User"), text: $model.username)
                    .textContentType(.username)
                    .autocorrectionDisabled()
                #if os(iOS)
                    .textInputAutocapitalization(.never)
                #endif
                SecureField(.reachy("Password"), text: $model.password)
                    .textContentType(.password)
                    .onSubmit(onConnect)
            } header: {
                Text(.reachy("Sign in to the robot"))
            } footer: {
                Text(.reachy(
                    "A Reachy Mini Wireless ships with the user pollen and the password root. Change it on the robot — anyone on this network can use it."
                ))
            }

            if let error = model.lastError {
                Section {
                    Text(error)
                        .font(Typography.detail)
                        .foregroundStyle(Tone.danger.style)
                }
            }

            Section {
                Button(.reachy("Connect"), action: onConnect)
                    .disabled(model.password.isEmpty || model.username.isEmpty)
            }
        }
        .formStyle(.grouped)
    }
}

/// Trust on first use, and the far more serious case of a key that changed.
///
/// One view for both because the fingerprint block is the same and the difference
/// is entirely in what the screen is willing to say about it.
struct HostKeyConfirmation: View {
    enum Situation: Equatable {
        case firstContact(HostKeyFingerprint)
        case changed(pinned: HostKeyFingerprint, offered: HostKeyFingerprint)
    }

    let situation: Situation
    let onTrust: () -> Void

    var body: some View {
        Form {
            Section {
                Text(offered.groupedForDisplay)
                    .font(Typography.consoleLine)
                    .textSelection(.enabled)
                LabeledContent(.reachy("Algorithm"), value: offered.algorithm)
            } header: {
                Text(.reachy("Robot identity key"))
            } footer: {
                Text(footer)
            }

            if case let .changed(pinned, _) = situation {
                Section {
                    Text(pinned.groupedForDisplay)
                        .font(Typography.consoleLine)
                        .textSelection(.enabled)
                } header: {
                    Text(.reachy("Key you trusted before"))
                }
            }

            Section {
                Button(trustTitle, action: onTrust)
                    .foregroundStyle(isChange ? Tone.danger.style : AnyShapeStyle(.tint))
            }
        }
        .formStyle(.grouped)
        .navigationTitle(isChange ? .reachy("Identity changed") : .reachy("New robot"))
    }

    private var isChange: Bool {
        if case .changed = situation { return true }
        return false
    }

    private var offered: HostKeyFingerprint {
        switch situation {
        case let .firstContact(fingerprint): fingerprint
        case let .changed(_, offered): offered
        }
    }

    private var trustTitle: LocalizedStringResource {
        isChange ? .reachy("Trust the new key") : .reachy("Trust this robot")
    }

    private var footer: LocalizedStringResource {
        if isChange {
            // swiftlint:disable:next line_length
            .reachy("This robot answered with a different key than the one you trusted. That happens after the robot is reflashed — and it is also what someone impersonating it would look like. Only continue if you know why it changed.")
        } else {
            // swiftlint:disable:next line_length
            .reachy("This is the first time this app has connected to this robot over SSH. Compare the key with ssh-keygen -lf on the robot if you want to be certain.")
        }
    }
}

import ReachyDesign
import ReachySSH
import SwiftUI
import UniformTypeIdentifiers

/// The robot's own file system, over SFTP.
///
/// The one screen in this app that reaches the robot without the daemon, because
/// the daemon has no route for it: nothing in its 77 paths writes an arbitrary
/// file. That is also the whole of its remit — no motion, no media, no service
/// commands (project rule 2 and `ReachySSH/AGENTS.md`).
///
/// Editing is deliberately not here. A file goes to the device, an editor there
/// changes it, and it comes back over the same path — which is why the row menu
/// offers Replace as well as Download.
struct RobotFilesScreen: View {
    @State private var model: RobotFilesModel
    @State private var exported: RemoteFileDocument?
    @State private var exportName = ""
    @State private var isImporting = false
    /// Set when Replace was chosen on a row, so the import lands on that path
    /// instead of on a new name in the current directory.
    @State private var replacing: RemoteFile?
    @State private var newFolderName = ""
    @State private var isNamingFolder = false
    @State private var renaming: RemoteFile?
    @State private var renameDraft = ""
    @Environment(\.reachyPreviewMode) private var previewMode

    init(model: RobotFilesModel) {
        _model = State(initialValue: model)
    }

    var body: some View {
        content
            .navigationTitle(.reachy("Files"))
            .task {
                // A frozen preview must not open a socket.
                guard previewMode == .live else { return }
                await model.start()
            }
    }

    @ViewBuilder
    private var content: some View {
        switch model.phase {
        case .idle, .connecting:
            Color.clear
                .contentLoading(isPresented: true, title: .reachy("Connecting over SSH…"))
        case .needsPassword:
            SSHPasswordForm(model: model) { Task { await model.connect() } }
        case let .confirmHostKey(fingerprint):
            HostKeyConfirmation(situation: .firstContact(fingerprint)) {
                Task { await model.trustOfferedKey() }
            }
        case let .hostKeyChanged(pinned, offered):
            HostKeyConfirmation(situation: .changed(pinned: pinned, offered: offered)) {
                Task { await model.trustOfferedKey() }
            }
        case let .failed(reason):
            ContentUnavailableView {
                Label(.reachy("Cannot reach the robot's files"), systemImage: "folder.badge.questionmark")
            } description: {
                Text(reason)
            } actions: {
                Button(.reachy("Try again")) { Task { await model.connect() } }
            }
        case .browsing:
            listing
        }
    }

    // MARK: - Browsing

    private var listing: some View {
        List {
            if let error = model.lastError {
                Section {
                    Text(error)
                        .font(Typography.detail)
                        .foregroundStyle(Tone.danger.style)
                }
            }
            placesSection
            Section {
                ForEach(model.entries) { file in
                    row(for: file)
                }
            } header: {
                Text(model.path)
                    .font(Typography.consoleLine)
                    .textCase(nil)
            }
        }
        .overlay {
            if model.hasListed, model.entries.isEmpty, model.lastError == nil {
                ContentUnavailableView {
                    Label(.reachy("Nothing here"), systemImage: "folder")
                } description: {
                    Text(.reachy("This folder is empty."))
                }
            }
        }
        .contentLoading(isPresented: !model.hasListed, title: .reachy("Reading the folder…"))
        .refreshable { await model.refresh() }
        .toolbar { toolbarContent }
        .modifier(FileTransferModifier(
            model: model,
            exported: $exported,
            exportName: $exportName,
            isImporting: $isImporting,
            replacing: $replacing
        ))
        .alert(.reachy("New folder"), isPresented: $isNamingFolder) {
            TextField(.reachy("Name"), text: $newFolderName)
            Button(.reachy("Cancel"), role: .cancel) { newFolderName = "" }
            Button(.reachy("Create")) {
                let name = newFolderName
                newFolderName = ""
                Task { await model.makeDirectory(named: name) }
            }
        }
        .alert(.reachy("Rename"), isPresented: renameBinding) {
            TextField(.reachy("Name"), text: $renameDraft)
            Button(.reachy("Cancel"), role: .cancel) { renaming = nil }
            Button(.reachy("Rename")) {
                if let file = renaming {
                    let name = renameDraft
                    Task { await model.rename(file, to: name) }
                }
                renaming = nil
            }
        }
        .confirmationDialog(
            .reachy("Delete from the robot?"),
            isPresented: confirmingBinding,
            titleVisibility: .visible
        ) {
            if case let .delete(file) = model.confirming {
                Button(.reachy("Delete"), role: .destructive) {
                    model.confirming = nil
                    Task { await model.delete(file) }
                }
            }
            Button(.reachy("Cancel"), role: .cancel) { model.confirming = nil }
        } message: {
            Text(.reachy("This cannot be undone from here. Download a copy first if you might need it."))
        }
    }

    /// Shortcuts, not a jail: the root stays reachable. The middle one is the
    /// directory a broken app's instance data lives in, which is why this screen
    /// exists at all.
    private var placesSection: some View {
        Section {
